// Command specprep turns the Swagger 2.0 document generated by DevLake's
// `make swag` into a clean OpenAPI 3 document that oapi-codegen can consume.
//
// DevLake's spec is produced from swaggo annotations and carries a number of
// quirks that generators trip over. specprep fixes them deterministically:
//
//   - gin style path parameters (/projects/:projectName) become {projectName}
//     and path items that collide after that rewrite are merged
//   - documentation-only paths (e.g. /pipelines/jira/pipeline-task) that only
//     exist to publish option schemas are removed; their schemas are kept
//   - operations get stable, generated operationIds
//   - operations with several body parameters get a single body
//   - path parameters are reconciled with the path template
//   - the result is converted to OpenAPI 3 and validated
//
// Usage: specprep -in spec/swagger.json -out spec/openapi.json
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"regexp"
	"sort"
	"strings"
	"unicode"

	"github.com/getkin/kin-openapi/openapi2"
	"github.com/getkin/kin-openapi/openapi2conv"
	"github.com/getkin/kin-openapi/openapi3"
)

func main() {
	in := flag.String("in", "spec/swagger.json", "input Swagger 2.0 document")
	out := flag.String("out", "spec/openapi.json", "output OpenAPI 3 document")
	version := flag.String("version", "", "DevLake version to record in info.version")
	overridesPath := flag.String("overrides", "spec/overrides.json", "JSON file with per-operation overrides (optional)")
	flag.Parse()

	raw, err := os.ReadFile(*in)
	if err != nil {
		log.Fatalf("read input: %v", err)
	}
	var overrides map[string]obj
	if b, err := os.ReadFile(*overridesPath); err == nil {
		if err := json.Unmarshal(b, &overrides); err != nil {
			log.Fatalf("decode overrides: %v", err)
		}
	} else if !os.IsNotExist(err) {
		log.Fatalf("read overrides: %v", err)
	}
	doc, err := Prepare(raw, *version, overrides)
	if err != nil {
		log.Fatalf("prepare: %v", err)
	}
	if err := os.WriteFile(*out, doc, 0o644); err != nil {
		log.Fatalf("write output: %v", err)
	}
}

type obj = map[string]any

var httpMethods = []string{"get", "put", "post", "delete", "options", "head", "patch"}

// docOnlyPath matches endpoints that DevLake documents but does not serve.
// They exist so that swag publishes the plugin option schemas.
var docOnlyPath = regexp.MustCompile(`^/(pipelines|blueprints)/[^/{}]+/(pipeline-(task|plan)|blueprint-(plan|setting))$`)

var definitionPrefix = regexp.MustCompile(`("|#/definitions/)github_com_apache_(?:incubator_)?devlake_(?:plugins_)?`)

// integerPathParams are numeric IDs in DevLake but are annotated as strings
// in some handlers. Forcing them to integers gives a consistent Go API.
var integerPathParams = map[string]bool{
	"connectionId": true, "blueprintId": true, "pipelineId": true,
	"taskId": true, "apiKeyId": true, "scopeConfigId": true,
}

var ginParam = regexp.MustCompile(`/:([A-Za-z0-9_]+)`)
var templateParam = regexp.MustCompile(`\{([A-Za-z0-9_]+)\}`)

// Prepare runs every fix and returns an indented OpenAPI 3 JSON document.
//
// overrides maps "METHOD /path" (after path rewriting, e.g. "get /version")
// to operation fields that replace the generated ones. Use it for handlers
// whose swag annotations do not match what DevLake actually returns.
func Prepare(raw []byte, version string, overrides map[string]obj) ([]byte, error) {
	// Shorten fully qualified definition names such as
	// github_com_apache_devlake_plugins_gitlab_api.ScopeDetail -> gitlab_api.ScopeDetail
	raw = definitionPrefix.ReplaceAll(raw, []byte("$1"))

	var sw obj
	if err := json.Unmarshal(raw, &sw); err != nil {
		return nil, fmt.Errorf("decode swagger: %w", err)
	}

	paths, _ := sw["paths"].(obj)
	cleaned := mergePaths(paths)

	usedIDs := map[string]int{}
	for _, p := range sortedKeys(cleaned) {
		item := cleaned[p].(obj)
		for _, m := range httpMethods {
			op, ok := item[m].(obj)
			if !ok {
				continue
			}
			fixParams(p, op)
			fixResponses(op, hasDefinition(sw, "shared.ApiBody"))
			if ov, ok := overrides[m+" "+p]; ok {
				for k, v := range ov {
					op[k] = v
				}
				delete(overrides, m+" "+p)
			}
			id := operationID(m, p)
			if n := usedIDs[id]; n > 0 {
				usedIDs[id] = n + 1
				id = fmt.Sprintf("%s%d", id, n+1)
			} else {
				usedIDs[id] = 1
			}
			op["operationId"] = id
		}
	}
	if len(overrides) > 0 {
		return nil, fmt.Errorf("overrides for unknown operations: %v", sortedKeys(overrides))
	}
	sw["paths"] = cleaned
	fixDefinitions(sw)

	info, _ := sw["info"].(obj)
	if info == nil {
		info = obj{}
	}
	info["title"] = "Apache DevLake API"
	info["description"] = "Normalized from the Swagger document generated by Apache DevLake."
	if version != "" {
		info["version"] = version
	}
	sw["info"] = info

	fixedRaw, err := json.Marshal(sw)
	if err != nil {
		return nil, err
	}
	var doc2 openapi2.T
	if err := json.Unmarshal(fixedRaw, &doc2); err != nil {
		return nil, fmt.Errorf("decode fixed swagger: %w", err)
	}
	doc3, err := openapi2conv.ToV3(&doc2)
	if err != nil {
		return nil, fmt.Errorf("convert to openapi 3: %w", err)
	}
	doc3.Servers = openapi3.Servers{{URL: "/api", Description: "DevLake behind config-ui (use / for a direct backend connection)"}}
	if err := doc3.Validate(context.Background(), openapi3.DisableExamplesValidation()); err != nil {
		return nil, fmt.Errorf("validate openapi 3: %w", err)
	}
	return json.MarshalIndent(doc3, "", "  ")
}

// fixResponses makes sure every operation has a response and that error
// responses use DevLake's real error envelope instead of a bare string.
func fixResponses(op obj, haveAPIBody bool) {
	rs, _ := op["responses"].(obj)
	if len(rs) == 0 {
		op["responses"] = obj{"200": obj{"description": "OK"}}
		return
	}
	if !haveAPIBody {
		return
	}
	for code, r := range rs {
		rr, ok := r.(obj)
		if !ok || len(code) != 3 || code[0] < '4' {
			continue
		}
		if sc, ok := rr["schema"].(obj); ok && sc["type"] == "string" {
			rr["schema"] = obj{"$ref": "#/definitions/shared.ApiBody"}
		}
	}
}

func hasDefinition(sw obj, name string) bool {
	defs, _ := sw["definitions"].(obj)
	_, ok := defs[name]
	return ok
}

// mergePaths rewrites gin style parameters, drops documentation-only paths and
// merges path items that only differ in the names of their path parameters
// (e.g. /scopes/{scopeId} and /scopes/{boardId}). The variant with the most
// operations provides the canonical parameter names.
func mergePaths(paths obj) obj {
	groups := map[string][]string{} // shape -> rewritten paths
	items := map[string]obj{}       // rewritten path -> merged item
	for _, p := range sortedKeys(paths) {
		if docOnlyPath.MatchString(p) {
			continue
		}
		np := ginParam.ReplaceAllString(p, "/{$1}")
		item, _ := paths[p].(obj)
		existing := items[np]
		if existing == nil {
			existing = obj{}
			shape := templateParam.ReplaceAllString(np, "{}")
			groups[shape] = append(groups[shape], np)
		}
		for k, v := range item {
			if _, dup := existing[k]; !dup {
				existing[k] = v
			}
		}
		items[np] = existing
	}

	out := obj{}
	for _, shape := range sortedKeys(groups) {
		variants := groups[shape]
		canonical := variants[0]
		for _, v := range variants[1:] {
			if len(items[v]) > len(items[canonical]) {
				canonical = v
			}
		}
		merged := items[canonical]
		canonNames := templateParam.FindAllStringSubmatch(canonical, -1)
		for _, v := range variants {
			if v == canonical {
				continue
			}
			names := templateParam.FindAllStringSubmatch(v, -1)
			rename := map[string]string{}
			for i := range names {
				rename[names[i][1]] = canonNames[i][1]
			}
			for k, opRaw := range items[v] {
				if _, dup := merged[k]; dup {
					continue
				}
				if op, ok := opRaw.(obj); ok {
					if ps, ok := op["parameters"].([]any); ok {
						for _, pr := range ps {
							if pp, ok := pr.(obj); ok && pp["in"] == "path" {
								if n, ok := rename[pp["name"].(string)]; ok {
									pp["name"] = n
								}
							}
						}
					}
				}
				merged[k] = opRaw
			}
		}
		out[canonical] = merged
	}
	return out
}

// fixParams reconciles the parameters of a single operation.
func fixParams(path string, op obj) {
	params, _ := op["parameters"].([]any)
	inPath := map[string]bool{}
	for _, m := range templateParam.FindAllStringSubmatch(path, -1) {
		inPath[m[1]] = true
	}

	var out []any
	var bodies []obj
	seen := map[string]bool{}
	hasFormData := false
	for _, raw := range params {
		prm, ok := raw.(obj)
		if !ok {
			continue
		}
		in, _ := prm["in"].(string)
		name, _ := prm["name"].(string)
		key := in + ":" + name
		if seen[key] {
			continue
		}
		seen[key] = true
		switch in {
		case "body":
			bodies = append(bodies, prm)
			continue
		case "path":
			if !inPath[name] {
				continue // documented but not part of the template
			}
			prm["required"] = true
			if integerPathParams[name] {
				prm["type"] = "integer"
				delete(prm, "schema")
			}
			if _, ok := prm["type"]; !ok {
				prm["type"] = "string"
				delete(prm, "schema")
			}
			delete(inPath, name)
		case "formData":
			hasFormData = true
		}
		out = append(out, prm)
	}
	// Path parameters present in the template but never declared.
	for _, name := range sortedKeys(inPath) {
		typ := "string"
		if integerPathParams[name] {
			typ = "integer"
		}
		out = append(out, obj{"name": name, "in": "path", "required": true, "type": typ})
	}
	if b := mergeBodies(bodies); b != nil && !hasFormData {
		out = append(out, b)
	}
	op["parameters"] = out
}

// mergeBodies folds several body parameters into one. swaggo users often
// document each JSON field as a separate body parameter.
func mergeBodies(bodies []obj) obj {
	switch len(bodies) {
	case 0:
		return nil
	case 1:
		b := bodies[0]
		if _, ok := b["schema"]; !ok {
			b["schema"] = obj{"type": "object"}
		}
		return b
	}
	first, _ := json.Marshal(bodies[0]["schema"])
	same := true
	for _, b := range bodies[1:] {
		s, _ := json.Marshal(b["schema"])
		if string(s) != string(first) {
			same = false
			break
		}
	}
	if same {
		b := bodies[0]
		b["name"] = "body"
		return b
	}
	props := obj{}
	for _, b := range bodies {
		name, _ := b["name"].(string)
		schema := b["schema"]
		if schema == nil {
			schema = obj{}
		}
		props[name] = schema
	}
	return obj{"name": "body", "in": "body", "schema": obj{"type": "object", "properties": props}}
}

// fixDefinitions repairs schema quirks in the definitions section.
func fixDefinitions(sw obj) {
	defs, _ := sw["definitions"].(obj)
	for _, name := range sortedKeys(defs) {
		walkSchema(defs[name])
	}
	paths, _ := sw["paths"].(obj)
	for _, item := range paths {
		for _, op := range item.(obj) {
			o, ok := op.(obj)
			if !ok {
				continue
			}
			if rs, ok := o["responses"].(obj); ok {
				for _, r := range rs {
					if rr, ok := r.(obj); ok {
						walkSchema(rr["schema"])
					}
				}
			}
			if ps, ok := o["parameters"].([]any); ok {
				for _, p := range ps {
					if pp, ok := p.(obj); ok {
						walkSchema(pp["schema"])
					}
				}
			}
		}
	}
}

func walkSchema(v any) {
	s, ok := v.(obj)
	if !ok {
		return
	}
	if req, ok := s["required"].([]any); ok {
		seen := map[any]bool{}
		var uniq []any
		for _, r := range req {
			if !seen[r] {
				seen[r] = true
				uniq = append(uniq, r)
			}
		}
		s["required"] = uniq
	}
	// swag renders `any` / interface{} as an empty schema; that is fine.
	// It renders time.Duration and similar as integer with enums of names.
	if enum, ok := s["enum"].([]any); ok {
		if t, _ := s["type"].(string); t == "integer" {
			for _, e := range enum {
				if _, isNum := e.(float64); !isNum {
					delete(s, "enum")
					delete(s, "x-enum-varnames")
					break
				}
			}
		}
	}
	for _, k := range []string{"items", "additionalProperties"} {
		walkSchema(s[k])
	}
	if props, ok := s["properties"].(obj); ok {
		for _, p := range props {
			walkSchema(p)
		}
	}
	for _, k := range []string{"allOf", "anyOf", "oneOf"} {
		if list, ok := s[k].([]any); ok {
			for _, x := range list {
				walkSchema(x)
			}
		}
	}
}

// operationID builds an identifier such as GetPluginsJiraConnectionsConnectionId.
func operationID(method, path string) string {
	var b strings.Builder
	b.WriteString(upperFirst(method))
	for _, seg := range strings.Split(path, "/") {
		seg = strings.Trim(seg, "{}")
		b.WriteString(camel(seg))
	}
	return b.String()
}

func camel(s string) string {
	var b strings.Builder
	up := true
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			up = true
			continue
		}
		if up {
			b.WriteRune(unicode.ToUpper(r))
			up = false
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
